/** Strip the highlight identity (testid, classes, colours) off every `annotation-<kind>` element. */
export const scrubAnnotationDom = (root: ParentNode, kind: string): void => {
  for (const element of root.querySelectorAll(`[data-testid="annotation-${kind}"]`)) {
    element.removeAttribute("data-testid");
    element.removeAttribute("class");
    if (element instanceof HTMLElement) {
      element.style.backgroundColor = "transparent";
      element.style.color = "inherit";
    }
  }
};

/**
 * Last-resort DOM scrub for the cancelled composer highlight (symbiot#236).
 *
 * Under CI contention slate-react intermittently fails to repaint the blurred
 * read-only editable after the overlay-dismiss cancel — a stale
 * `annotation-<kind>` element survives model rollbacks, decoration clears,
 * `redecorate()`, and even `<Plate>` remounts. When this runs (deferred, after
 * the cancel commit) the model holds no leaf of the kind and no pending
 * decoration is active, so every remaining element of that kind is provably
 * orphaned — nothing in the model, decorations, or VDOM backs it. Attributes
 * are stripped instead of removing the node so a still-fiber-attached element
 * remains structurally intact for any later React commit.
 *
 * Returns whether a scrub pass actually ran (false when a guard bailed).
 */
export const scrubOrphanedPendingHighlight = (
  editor: SlateEditor,
  kind: PendingHighlightKind
): boolean => {
  if (pendingByEditor.has(editor)) return false;
  const prefix = prefixOf(kind);
  const marked = editor.api.nodes({
    at: [],
    match: (node) => TextApi.isText(node) && node[prefix] === true,
  });
  if (!marked.next().done) return false;
  let editable: HTMLElement;
  try {
    editable = editor.api.toDOMNode(editor);
  } catch {
    // The editor unmounted between the deferred call and now — no DOM to scrub.
    return false;
  }
  scrubAnnotationDom(editable, kind);
  return true;
};

